const D = { energy: .6, scale: 1, density: .5, speed: 1, wear: .5, hue: 40, x: .5, y: .5, style: 'limestone', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- A broad stone staircase climbing away to the horizon — lit tread tops and shadowed
// risers banding the plane, the nosings worn round and polished down the middle where a
// thousand feet have gone, and a raking light pool travelling up the flight so the bright
// step keeps moving. A ground plane (painted BELOW the horizon only); new floor family. ----

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height), sd = P.seed|0;
function hsh(ix,iy){ let h=(Math.imul(ix,374761393)+Math.imul(iy,668265263)+Math.imul(sd,1442695041))|0;
  h=Math.imul(h^(h>>>13),1274126177)|0; return ((h^(h>>>16))>>>0)/4294967295; }
function vn(x,y){ const ix=Math.floor(x), iy=Math.floor(y), fx=x-ix, fy=y-iy;
  const wx=fx*fx*(3-2*fx), wy=fy*fy*(3-2*fy);
  const a=hsh(ix,iy), b=hsh(ix+1,iy), c=hsh(ix,iy+1), d=hsh(ix+1,iy+1);
  return a+(b-a)*wx+(c-a)*wy+(a-b-c+d)*wx*wy; }
function fbm(x,y){ return .55*vn(x,y)+.28*vn(x*2.03+5.1,y*2.03-3.3)+.17*vn(x*4.07-2.7,y*4.07+7.9); }
function hsv(h,s,v){ h=(((h%360)+360)%360)/60; const c=v*s, xx=c*(1-Math.abs(h%2-1)), m=v-c;
  let r,g2,b2;
  if(h<1){r=c;g2=xx;b2=0}else if(h<2){r=xx;g2=c;b2=0}else if(h<3){r=0;g2=c;b2=xx}
  else if(h<4){r=0;g2=xx;b2=c}else if(h<5){r=xx;g2=0;b2=c}else{r=c;g2=0;b2=xx}
  return [(r+m)*255,(g2+m)*255,(b2+m)*255]; }

const sty = P.style, en = cl(P.energy,0,1), wr = cl(P.wear,0,1), dn = cl(P.density,0,1);
const Hh = ((P.hue%360)+360)%360, tt = K.t;
const bp = sty==='blueprint', wet = sty==='wet', moss = sty==='moss', dk = sty==='chiaroscuro';

const vy = cl(P.y,.18,.78)*height, vx = cl(P.x,.05,.95)*width;
const f = u*.92, H0 = 1;
const TD = .30*cl(P.scale,.35,2.6);                   // tread depth in world units

// the camera climbs the flight, so the steps stream steadily down past us (perpetual, never
// re-phases); on top of that a raking light pool crawls up and down the run.
if (S.z == null) S.z = 0;
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
S.z += dt * P.speed * (.09 + .13*K.intensity) * (.5 + .7*en);
const zoff = S.z;
const bass = (S.b = (S.b||0)*.82 + (A.bass||0)*.18);
const Lz = 2.6 + 2.2*Math.sin(tt*.083*P.speed) + 1.1*Math.sin(tt*.169*P.speed+1.3) + .6*Math.sin(tt*.31+2.1);
const Lz2 = 5.4 + 2.8*Math.sin(tt*.057*P.speed+2.0) + 1.3*Math.sin(tt*.127*P.speed+.5);
const Lx = 1.4*Math.sin(tt*.071) + .7*Math.sin(tt*.153+1.1);
const glow = (.42+.58*en)*(.55+.5*K.intensity) + bass*.26;

let stoneD, stoneL, riserC, litC;
if (bp)        { stoneD=[212,74,12]; stoneL=[190,44,78]; riserC=[214,80,7];  litC=[186,52,92]; }
else if (wet)  { stoneD=[Hh+8,26,10]; stoneL=[Hh+2,14,58]; riserC=[Hh+10,30,6]; litC=[Hh-6,10,84]; }
else if (moss) { stoneD=[Hh+4,10,20]; stoneL=[Hh,7,66];  riserC=[100,44,16];  litC=[Hh,5,80]; }
else if (dk)   { stoneD=[Hh,12,5];   stoneL=[Hh,10,64];  riserC=[Hh,14,3];    litC=[Hh-6,6,92]; }
else           { stoneD=[Hh,20,24];  stoneL=[Hh-4,13,80]; riserC=[Hh+4,24,12]; litC=[Hh-8,8,90]; }
const cSd=hsv(stoneD[0],stoneD[1]/100,stoneD[2]/100), cSl=hsv(stoneL[0],stoneL[1]/100,stoneL[2]/100);
const cRs=hsv(riserC[0],riserC[1]/100,riserC[2]/100), cLt=hsv(litC[0],litC[1]/100,litC[2]/100);

const BW = Math.max(360,Math.min(720,Math.round(width/2.4))), BH = Math.max(44, Math.round(BW*height/width));
if (!S.g || S.bk !== BW+'x'+BH){ if(S.g){ try{S.g.remove();}catch(e){} }
  S.g = createGraphics(BW,BH); S.g.pixelDensity(1); S.bk = BW+'x'+BH; }
const g = S.g; g.loadPixels(); const px = g.pixels;

const AL = P.alpha/100, treadFrac = .60 + wr*.06;
const j0 = Math.max(0, Math.floor((vy/height)*BH));
for (let j=0;j<j0;j++) for (let i=0;i<BW;i++) px[4*(j*BW+i)+3] = 0;

for (let j=j0;j<BH;j++){
  const sy = (j+.5)/BH*height, dy = sy - vy;
  if (dy < .35){ for (let i=0;i<BW;i++) px[4*(j*BW+i)+3] = 0; continue; }
  const Z = f*H0/dy, wz = Z;
  const far = cl((Z-1.1)/9, 0, 1);
  const det = cl(1 - far*1.02, .05, 1);
  const sfrac = (Z+zoff)/TD, sidx = Math.floor(sfrac), loc = sfrac - sidx;
  const isRiser = loc > treadFrac;                    // vertical face of the next step up
  const nosing = cl(1 - Math.abs(loc)/.06, 0, 1) + cl(1-Math.abs(loc-treadFrac)/.05,0,1);
  const q = hsh((sidx*131)&2047, ((sidx*29)>>>0)&2047);
  // light rake: which step the pool sits on
  const poolZ = Math.exp(-Math.pow((Z-Lz)/(1.0+TD*2),2))*1.0 + Math.exp(-Math.pow((Z-Lz2)/(1.6+TD*2),2))*.7;
  for (let i=0;i<BW;i++){
    const sx = (i+.5)/BW*width, X = (sx-vx)*Z/f;
    const o = 4*(j*BW+i);
    const poolX = Math.exp(-Math.pow((X-Lx)/2.4,2));
    const pool = poolZ*(.4+.6*poolX);
    // ---- base step shading: tread lit, riser in shadow ----
    let base = isRiser ? (.24 + q*.10) : (.46 + q*.20);
    base *= (.6 + .5*(isRiser?.3:1)*(1+pool*glow*.9));
    // worn nosing: rounded, polished, catches a sharp highlight down the middle
    const worn = cl(1-Math.abs(X)/(.7+.4*Math.sin(Z*.3)),0,1)*wr;
    let lum = base + nosing*(.20+glow*pool*.5)*(.5+worn*.7);
    lum -= isRiser? .05 : 0;
    // stone grain / wear pitting
    const grain = fbm(X*40+sidx*3.1, Z*40)*det + (1-det)*.5;
    lum *= .8 + grain*.4;
    lum = cl(lum, 0, 1.5);
    let r = cSd[0]+(cSl[0]-cSd[0])*lum, g2 = cSd[1]+(cSl[1]-cSd[1])*lum, b2 = cSd[2]+(cSl[2]-cSd[2])*lum;
    // riser material shift (shadowed / mossy)
    if (isRiser){ r += (cRs[0]-r)*.5; g2 += (cRs[1]-g2)*.5; b2 += (cRs[2]-b2)*.5; }
    // hot specular on the lit worn nosings
    const hot = cl((nosing*pool*glow*(.5+worn) - .35)*1.8,0,1);
    r += (cLt[0]-r)*hot*.55; g2 += (cLt[1]-g2)*hot*.55; b2 += (cLt[2]-b2)*hot*.55;
    if (moss){
      const mo = cl((fbm(X*6+3.1,Z*6)-.44)*3.0,0,1)*(isRiser?.7:.3)*(.4+wr*.8);
      r += (cRs[0]*1.2-r)*mo*.7; g2 += (cRs[1]*1.5-g2)*mo*.7; b2 += (cRs[2]*1.1-b2)*mo*.7;
    }
    if (wet && !isRiser){
      const rip = .5+.5*Math.sin(Z*14 - tt*1.8 + X*5 + fbm(X*3,Z*3-tt*.4)*4);
      const spec = cl((.5-Math.abs(loc-treadFrac*.5)/.4),0,1)*(.2+pool*glow*1.3)*(.55+rip*.7);
      r += (cLt[0]-r)*spec*.6; g2 += (cLt[1]-g2)*spec*.6; b2 += (cLt[2]-b2)*spec*.6;
    }
    if (bp){
      const on = (nosing>.4 || isRiser&&loc>treadFrac+.001&&loc<treadFrac+.03) ? 1 : 0;
      const v2=.12+.10*(1-far);
      r=on?74:v2*40; g2=on?196*det+34:v2*100; b2=on?244:v2*172;
    }
    // subtle wall vignette at the extreme sides so it reads as a flight, not endless floor
    const vig = cl((Math.abs(X)-2.2)/1.5,0,1);
    r*=1-vig*.5; g2*=1-vig*.5; b2*=1-vig*.45;
    const hazeK = far*far*.85;
    const hc = bp? [40,120,190] : [cSl[0]*.72, cSl[1]*.72, cSl[2]*.78];
    r += (hc[0]-r)*hazeK; g2 += (hc[1]-g2)*hazeK; b2 += (hc[2]-b2)*hazeK;
    px[o]=cl(r,0,255); px[o+1]=cl(g2,0,255); px[o+2]=cl(b2,0,255);
    px[o+3]=255*AL*cl(1-far*far*.72,0,1)*cl(dy/2.2,0,1);
  }
}
g.updatePixels();
push(); image(g,0,0,width,height); pop();

// ---- dust / drift low over the steps, crisp ----
push(); blendMode(ADD); noStroke();
const NM = Math.round(4 + dn*30);
for (let i=0;i<NM;i++){
  const a1=hsh(i*13+7,3), a2=hsh(i*13+8,5), a3=hsh(i*13+9,11);
  const mz=((a2+tt*(.016+a3*.05)*P.speed)%1.05);
  const my=vy+Math.pow(mz,2.0)*(height-vy)*1.02;
  const mx=(a1+Math.sin(tt*(.14+a3*.34)+a1*6.28)*.05)*width;
  const sz=u*(.0012+a3*.004)*(.4+mz*1.7);
  fill(wet?Hh-6:Hh+16, bp?40:14, 100, (5+a3*10)*(.3+en)*AL*(1-mz*.4));
  ellipse(mx,my,sz,sz*.7);
}
blendMode(BLEND); pop();

